INSERT OR IGNORE INTO character_skills (skill_id, character_id, type, name_en, data_json) VALUES ('mahmut_basic_oathless_cut', 'mahmut', 'basic', 'Oathless Cut', '{"brand_mark_id":"mark_skill_mahmut_basic_oathless_cut","element":"Stone","target_rule":"single_enemy","scale_stat":"atk","multiplier":1,"multipliers_pct":[100,8],"cooldown_turns":0,"focus_cost":0,"focus_gain_rule":null,"description_en":"Deals physical damage equal to 100% of ATK to one enemy. If Mahmut is in the Front Row, he gains Stoneguard, reducing damage taken by 8% for 1 turn.","effect_ops":[{"op":"damage","target_selector_id":"single_enemy","damage_type":"physical","scale_stat":"atk","multiplier":1},{"op":"apply_status","target_selector_id":"self","status_id":"stoneguard","duration_turns":1,"when":{"predicate":"owner_in_row","value":"front"}}],"auto_priority":10}');
INSERT OR IGNORE INTO character_skills (skill_id, character_id, type, name_en, data_json) VALUES ('mahmut_active_broken_crest_guard', 'mahmut', 'active', 'Broken Crest Guard', '{"brand_mark_id":"mark_skill_mahmut_active_broken_crest_guard","element":"Stone","target_rule":"lowest_hp_ally","scale_stat":"atk","multiplier":null,"multipliers_pct":[180,50],"cooldown_turns":2,"focus_cost":0,"focus_gain_rule":null,"description_en":"Grants Mahmut and the ally with the lowest HP a shield equal to 180% of Mahmut''s ATK. For 2 turns, Mahmut redirects 50% of single-target attacks aimed at that ally to himself.","effect_ops":[{"op":"grant_shield","target_selector_id":"self_and_lowest_hp_ally","scale_stat":"atk","multiplier":1.8,"duration_turns":2},{"op":"grant_redirect","target_selector_id":"self","protected_ally_selector_id":"lowest_hp_ally","redirected_fraction":0.5,"duration_turns":2,"eligible_action_types":["basic","active","ultimate"]}],"auto_priority":30}');
INSERT OR IGNORE INTO character_skills (skill_id, character_id, type, name_en, data_json) VALUES ('mahmut_passive_a_knight_s_debt', 'mahmut', 'passive', 'A Knight''s Debt', '{"brand_mark_id":"mark_skill_mahmut_passive_a_knight_s_debt","element":"Stone","target_rule":"single_enemy","scale_stat":"atk","multiplier":null,"multipliers_pct":[60],"cooldown_turns":0,"focus_cost":0,"focus_gain_rule":"engine_event_defined","description_en":"While shielded, Mahmut counters an enemy Basic Attack for 60% of his ATK and gains 5 Focus. Triggers once per turn.","effect_ops":[],"auto_priority":0,"event_hooks":[{"event":"before_damage_received","effect_ops":[{"op":"damage","target_selector_id":"event_source","damage_type":"physical","scale_stat":"atk","multiplier":0.6,"no_focus_gain":true},{"op":"gain_focus","target_selector_id":"self","amount":5}],"condition":{"predicate":"owner_has_shield"},"limit":{"per_owner_turn":1},"event_filter":{"incoming_action_type":"basic"}}],"continuous_modifiers":[]}');
INSERT OR IGNORE INTO character_skills (skill_id, character_id, type, name_en, data_json) VALUES ('mahmut_ultimate_last_wall_at_dusk', 'mahmut', 'ultimate', 'Last Wall at Dusk', '{"brand_mark_id":"mark_skill_mahmut_ultimate_last_wall_at_dusk","element":"Stone","target_rule":"front_row_enemies","scale_stat":"atk","multiplier":2.2,"multipliers_pct":[220,120],"cooldown_turns":0,"focus_cost":100,"focus_gain_rule":null,"description_en":"Deals physical damage equal to 220% of ATK to all Front Row enemies, Taunts them for 2 turns, and grants all allies a shield equal to 120% of Mahmut''s DEF. The shield still applies if a boss resists Taunt.","effect_ops":[{"op":"damage","target_selector_id":"front_row_enemies","damage_type":"physical","scale_stat":"atk","multiplier":2.2},{"op":"apply_status","target_selector_id":"all_enemies","status_id":"taunt","duration_turns":2},{"op":"grant_shield","target_selector_id":"all_allies","scale_stat":"def","multiplier":1.2,"duration_turns":2}],"auto_priority":40}');
