INSERT OR IGNORE INTO character_skills (skill_id, character_id, type, name_en, data_json) VALUES ('fadyme_basic_veilglass_thorn', 'fadyme', 'basic', 'Veilglass Thorn', '{"brand_mark_id":"mark_skill_fadyme_basic_veilglass_thorn","element":"Veil","target_rule":"single_enemy","scale_stat":"atk","multiplier":1,"multipliers_pct":[100],"cooldown_turns":0,"focus_cost":0,"focus_gain_rule":"engine_event_defined","description_en":"Deals Veil magic damage equal to 100% of ATK to one enemy. Fadyme gains 5 additional Focus if the target is Dreaded.","effect_ops":[{"op":"damage","target_selector_id":"single_enemy","damage_type":"magic","scale_stat":"atk","multiplier":1},{"op":"gain_focus","target_selector_id":"self","amount":5,"when":{"predicate":"last_target_has_status","value":"dread"}}],"auto_priority":10}');
INSERT OR IGNORE INTO character_skills (skill_id, character_id, type, name_en, data_json) VALUES ('fadyme_active_borrowed_hour', 'fadyme', 'active', 'Borrowed Hour', '{"brand_mark_id":"mark_skill_fadyme_active_borrowed_hour","element":"Veil","target_rule":"single_enemy","scale_stat":"atk","multiplier":1.6,"multipliers_pct":[160,100],"cooldown_turns":2,"focus_cost":0,"focus_gain_rule":null,"description_en":"Deals Veil magic damage equal to 160% of ATK to one enemy and inflicts Dread for 2 turns. Heals the ally with the lowest HP for 100% of Fadyme''s ATK.","effect_ops":[{"op":"damage","target_selector_id":"single_enemy","damage_type":"magic","scale_stat":"atk","multiplier":1.6},{"op":"apply_status","target_selector_id":"previous_op_targets","status_id":"dread","duration_turns":2},{"op":"heal","target_selector_id":"lowest_hp_ally","scale_stat":"atk","multiplier":1}],"auto_priority":30}');
INSERT OR IGNORE INTO character_skills (skill_id, character_id, type, name_en, data_json) VALUES ('fadyme_passive_a_smile_kept', 'fadyme', 'passive', 'A Smile Kept', '{"brand_mark_id":"mark_skill_fadyme_passive_a_smile_kept","element":"Veil","target_rule":"all_allies","scale_stat":"atk","multiplier":null,"multipliers_pct":[50,8],"cooldown_turns":0,"focus_cost":0,"focus_gain_rule":null,"description_en":"At the start of her turn, if Fadyme is below 50% HP, all allies gain 8% Veil RES for 1 turn. Triggers up to 2 times per battle.","effect_ops":[],"auto_priority":0,"event_hooks":[{"event":"owner_turn_start","effect_ops":[{"op":"modify_stat","target_selector_id":"all_allies","stat_id":"veil_res","mode":"add_pct","amount":0.08,"duration_turns":1}],"condition":{"predicate":"owner_hp_below_pct","value":50},"limit":{"per_battle":2}}],"continuous_modifiers":[]}');
