INSERT OR IGNORE INTO game_config (key, value_json) VALUES ('tasks', '{"note":"Canon task structure (UTC 12-hour windows, Monday weekly cycle). Payouts are placeholders (Silver Crowns dropped, character XP as XP books); tuned in the final math pass.","windowHours":12,"daily":{"tasks":[{"id":"win_three_battles","title_en":"Win three battles","objective":{"type":"eligible_wins","count":3},"rewards":[{"type":"currency","currency":"eclipse_token","amount":80},{"type":"item","itemId":"bound_chronicle","quantity":3}]},{"id":"improve_company_kit","title_en":"Improve company kit","objective":{"type":"level_ups","count":1},"rewards":[{"type":"currency","currency":"eclipse_token","amount":40},{"type":"item","itemId":"bound_chronicle","quantity":1}]}],"completion":{"requires":["win_three_battles","improve_company_kit"],"rewards":[{"type":"item","itemId":"bound_chronicle","quantity":4},{"type":"account_xp","amount":400}]}},"weekly":{"claimGraceDays":7,"segments":[{"id":"cycle_a","title_en":"Cycle a","startDay":0,"durationDays":3,"objective":{"type":"eligible_wins","count":15},"rewards":[{"type":"currency","currency":"eclipse_token","amount":320},{"type":"item","itemId":"bound_chronicle","quantity":9}]},{"id":"cycle_b","title_en":"Cycle b","startDay":3,"durationDays":3,"objective":{"type":"boss_wins","count":5},"rewards":[{"type":"currency","currency":"eclipse_token","amount":320},{"type":"item","itemId":"bound_chronicle","quantity":9}]},{"id":"sun_eclipse","title_en":"Sun eclipse","startDay":6,"durationDays":1,"objective":{"type":"three_star_wins","count":3},"rewards":[{"type":"currency","currency":"eclipse_token","amount":160},{"type":"item","itemId":"bound_chronicle","quantity":2}]}]}}');
